// All Phosphor glyphs share a 256x256 box, so one viewBox serves every icon.
export function icon(name, { size = 16, className = '' } = {}) {
  const p = PATHS[name];
  if (!p) throw new Error(`unknown icon: ${name}`);
  return { __html: p, size, className };
}

export function iconSvg(name, size = 16) {
  const p = PATHS[name];
  if (!p) throw new Error(`unknown icon: ${name}`);
  return `<svg viewBox="0 0 256 256" width="${size}" height="${size}" ` +
         `fill="currentColor" aria-hidden="true" focusable="false">${p}</svg>`;
}

export const ICON_NAMES = Object.keys(PATHS);
